import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex, Select } from 'antd';

import FiltersIcon from 'assets/images/icons/filters.svg?react';
import { EFilters } from 'features/Filters/model/enums';

import { OPTIONS_MAX_HEIGHT_NOTIFICATIONS } from '../../consts';
import { useFilters } from '../../hooks/useFilters';

interface IPlannerFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const PlannerFilters: FC<IPlannerFiltersProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const { clearFilters, getFilterValue, onFilterChange } = useFilters();

	return (
		<Flex {...props} gap={8} className={className}>
			<Select
				value={getFilterValue(EFilters.OFFER_ID) || t('Все каналы и группы')}
				options={[]}
				onChange={(value) => onFilterChange(EFilters.OFFER_ID, value)}
				placeholder={t('Select offer')}
				size="large"
				showSearch
				listHeight={OPTIONS_MAX_HEIGHT_NOTIFICATIONS}
				style={{ width: '100%' }}
			/>

			<Button size="large" type="primary" onClick={clearFilters} icon={<FiltersIcon />}>
				{t('Фильтры')}
			</Button>
		</Flex>
	);
};
